head.script:
(function () {
  const XHTML_NS = "http://www.w3.org/1999/xhtml";

  const root =
    document.querySelector("foreignObject").firstElementChild;

  const head = root.querySelector("head");
  const body = root.querySelector("body");

  const originalCreateElement =
    document.createElement.bind(document);

  const originalCreateElementNS =
    document.createElementNS.bind(document);

  Object.defineProperty(document, "head", {
    get() { return head; },
    configurable: true
  });

  Object.defineProperty(document, "body", {
    get() { return body; },
    configurable: true
  });

  Object.defineProperty(document, "documentElement", {
    get() { return root; },
    configurable: true
  });

  document.createElement = function(tagName, options) {
    if (typeof tagName === "string") {
      return originalCreateElementNS(
        XHTML_NS,
        tagName,
        options
      );
    }

    return originalCreateElement(tagName, options);
  };

  document.createElementNS = function(
    namespaceURI,
    qualifiedName,
    options
  ) {
    if (
      namespaceURI == null ||
      namespaceURI === XHTML_NS
    ) {
      return originalCreateElementNS(
        XHTML_NS,
        qualifiedName,
        options
      );
    }

    return originalCreateElementNS(
      namespaceURI,
      qualifiedName,
      options
    );
  };

  if (!location.hash) {
    history.replaceState(history.state, "", "#/");
  }
})();

div.script:
const menuItems = [
  {
    label: 'Yuki OS',
    url:
      'https://quantil.jsdelivr.net/gh/reeyuki/YukiOsSingleHtml@main/yukios.svg'
  },

  {
    label: 'Lucide',
    url:
      'https://cdn.jsdelivr.net/gh/lucideproxy/svg@latest/logo.svg#/'
  },

  {
    label: 'Petezah',
    url:
      'https://originfastly.jsdelivr.net/gh/PeteZah-G/PeteZahStaticDone@959d81f/new.svg'
  },

  {
    label: 'Nikehub',
    url:
      'https://cdn.jsdelivr.net/gh/avaisadev/github.com@latest/index.svg'
  },

  {
    label: 'Fern',
    url:
      'https://d1w7oj52hl4x53.cloudfront.net/'
  }
];

// build buttons
const menuBody =
  document.getElementById('menu-buttons');

menuItems.forEach(item => {

  const btn =
    document.createElement('button');

  btn.className = 'menu-btn';

  btn.textContent = item.label;

  btn.onclick = () => {

    const win =
      window.open('about:blank', '_blank');

    if (!win) return;

    const iframe =
      win.document.createElement('iframe');

    iframe.src = item.url;

    iframe.style.cssText = `
      position:fixed;
      inset:0;
      width:100vw;
      height:100vh;
      border:none;
    `;

    win.document.body.style.margin = '0';

    win.document.body.appendChild(iframe);
  };

  menuBody.appendChild(btn);
});

// loader
const statuses = [
  'Initializing...',
  'Loading modules...',
  'Verifying integrity...',
  'Mounting resources...',
  'Ready.'
];

let si = 0;

const statusEl =
  document.getElementById('loader-status');

const statusInterval = setInterval(() => {

  si++;

  if (si < statuses.length) {
    statusEl.textContent = statuses[si];
  } else {
    clearInterval(statusInterval);
  }

}, 360);

setTimeout(() => {

  document
    .getElementById('loader')
    .classList.add('hide');

  document
    .getElementById('app')
    .classList.add('visible');

}, 2000);

// clock
function updateClock() {

  const now = new Date();

  const h =
    String(now.getHours()).padStart(2, '0');

  const m =
    String(now.getMinutes()).padStart(2, '0');

  const s =
    String(now.getSeconds()).padStart(2, '0');

  document.getElementById('clock')
    .textContent = `${h}:${m}:${s}`;
}

setInterval(updateClock, 1000);

updateClock();

// battery
async function initBattery() {

  if (!navigator.getBattery) return;

  const bat =
    await navigator.getBattery();

  function render() {

    const pct =
      Math.round(bat.level * 100);

    document
      .getElementById('battery-text')
      .textContent = pct + '%';
  }

  render();

  bat.addEventListener(
    'levelchange',
    render
  );
}

initBattery();

// ip
async function fetchIP() {

  try {

    const r = await fetch(
      'https://api.ipify.org?format=json'
    );

    const d = await r.json();

    document
      .getElementById('ip-display')
      .textContent = d.ip;

  } catch {

    document
      .getElementById('ip-display')
      .textContent = 'Unavailable';
  }
}

fetchIP();
